1	import {
2	  existsSync,
3	  readFileSync,
4	  writeFileSync,
5	  mkdirSync,
6	  createReadStream,
7	  createWriteStream,
8	  chmodSync,
9	  lstatSync,
10	  readlinkSync,
11	  renameSync,
12	  rmSync,
13	  symlinkSync,
14	} from 'node:fs';
15	import { mkdtemp, writeFile, mkdir, rm } from 'node:fs/promises';
16	import { delimiter, dirname, join, normalize, resolve, sep } from 'node:path';
17	import { homedir, tmpdir } from 'node:os';
18	import { execFile, spawn } from 'node:child_process';
19	import { promisify } from 'node:util';
20	import { pipeline } from 'node:stream/promises';
21	import { Readable } from 'node:stream';
22	import { createHash } from 'node:crypto';
23	import type { ReadableStream as WebReadableStream } from 'node:stream/web';
24	import { app } from 'electron';
25	import type { WebContents } from 'electron';
26	import type { RtkStatus, RtkSource, RtkDownloadProgress, RtkTestResult } from '@shared/types';
27	
28	const execFileAsync = promisify(execFile);
29	
30	// Cap download phases so a hung CDN cannot leave the single-flight promise
31	// pending forever — subsequent download() calls would await the dead promise.
32	const FETCH_API_TIMEOUT_MS = 60_000;
33	const FETCH_BODY_TIMEOUT_MS = 300_000;
34	const TAR_TIMEOUT_MS = 120_000;
35	
36	/** Managed-bin resolution wins over $PATH so uninstalling Dash leaves no orphan binary. */
37	export class RtkService {
38	  private static sender: WebContents | null = null;
39	  private static cachedResolution: {
40	    path: string;
41	    source: RtkSource;
42	    version: string;
43	  } | null = null;
44	  private static downloadInFlight: Promise<void> | null = null;
45	  // Mirrors the on-disk rtk-config.json flag; saves a disk read per hook write.
46	  // null = not yet loaded; hydrated on first isEnabled() call and after setEnabled().
47	  private static enabledCache: boolean | null = null;
48	  // Track whether we've already toasted a corrupt-config warning, so we don't
49	  // spam the user once per hook write — they only need to see it once.
50	  private static corruptConfigToasted = false;
51	
52	  static setSender(sender: WebContents): void {
53	    RtkService.sender = sender;
54	  }
55	
56	  private static getConfigPath(): string {
57	    return join(app.getPath('userData'), 'rtk-config.json');
58	  }
59	
60	  static isEnabled(): boolean {
61	    if (RtkService.enabledCache !== null) return RtkService.enabledCache;
62	    const p = RtkService.getConfigPath();
63	    if (!existsSync(p)) {
64	      RtkService.enabledCache = false;
65	      return false;
66	    }
67	    try {
68	      const raw = JSON.parse(readFileSync(p, 'utf-8')) as { enabled?: unknown };
69	      const value = raw.enabled === true;
70	      if (raw.enabled !== undefined && typeof raw.enabled !== 'boolean') {
71	        console.warn(
72	          '[RtkService.isEnabled] rtk-config.json "enabled" is not a boolean; treating as false.',
73	        );
74	        RtkService.notifyCorruptConfig(
75	          'RTK config has an invalid "enabled" value — RTK is off until you re-toggle it in Settings.',
76	        );
77	      }
78	      RtkService.enabledCache = value;
79	      return value;
80	    } catch (err) {
81	      console.error(
82	        '[RtkService.isEnabled] rtk-config.json unreadable, treating as disabled:',
83	        err,
84	      );
85	      // The user toggled RTK on at some point; a corrupt config now silently
86	      // means hooks stop firing in every spawn. Surface it instead of letting
87	      // the toggle keep showing ON while reality says OFF.
88	      RtkService.notifyCorruptConfig(
89	        `RTK config is unreadable (${err instanceof Error ? err.message : String(err)}) — RTK is off until you re-toggle it in Settings.`,
90	      );
91	      RtkService.enabledCache = false;
92	      return false;
93	    }
94	  }
95	
96	  /** Toast a corrupt-config warning once per process lifetime. */
97	  private static notifyCorruptConfig(message: string): void {
98	    if (RtkService.corruptConfigToasted) return;
99	    RtkService.corruptConfigToasted = true;
100	    const sender = RtkService.sender;
101	    if (sender && !sender.isDestroyed()) {
102	      sender.send('app:toast', { message });
103	    }
104	  }
105	
106	  /**
107	   * Enforces the "installed before enabled" invariant at the data layer so
108	   * callers outside the IPC handler can't write a config that lies about state.
109	   */
110	  static setEnabled(enabled: boolean): void {
111	    if (enabled && !RtkService.cachedResolution) {
112	      throw new Error('rtk is not installed');
113	    }
114	    const p = RtkService.getConfigPath();
115	    mkdirSync(dirname(p), { recursive: true });
116	    // Atomic write: tmp + rename so a crash here can never leave a half-
117	    // flushed JSON file that isEnabled() would treat as corrupt and silently
118	    // disable RTK on the next launch.
119	    const tmp = `${p}.tmp-${process.pid}-${Date.now()}`;
120	    writeFileSync(tmp, JSON.stringify({ enabled }, null, 2));
121	    renameSync(tmp, p);
122	    RtkService.enabledCache = enabled;
123	    // A successful write means the file is good. Clear the "we already toasted"
124	    // latch so a later re-corruption (manual edit, disk error) toasts again.
125	    RtkService.corruptConfigToasted = false;
126	  }
127	
128	  private static getManagedBinDir(): string {
129	    return join(app.getPath('userData'), 'bin');
130	  }
131	
132	  private static getManagedBinPath(): string {
133	    const exe = process.platform === 'win32' ? 'rtk.exe' : 'rtk';
134	    return join(RtkService.getManagedBinDir(), exe);
135	  }
136	
137	  /**
138	   * Path to a `~/.local/bin/rtk` symlink pointing at the managed binary.
139	   * RTK's hook rewrites `git status` → `rtk git status`, so `rtk` must resolve
140	   * via $PATH wherever Claude Code's Bash tool runs the rewritten command —
141	   * not just inside Dash's PTYs (whose PATH we control). `~/.local/bin` is on
142	   * $PATH by default on Linux and harmless on macOS. Returns null on Windows
143	   * because no native release exists upstream.
144	   */
145	  private static getUserPathSymlinkPath(): string | null {
146	    if (process.platform === 'win32') return null;
147	    return join(homedir(), '.local', 'bin', 'rtk');
148	  }
149	
150	  private static ensureUserBinSymlink(target: string): void {
151	    const linkPath = RtkService.getUserPathSymlinkPath();
152	    if (linkPath) ensureUserBinSymlink(target, linkPath);
153	  }
154	
155	  /**
156	   * Returns the managed bin dir ONLY when a probed-good binary is there.
157	   * Gating on cachedResolution (not just existsSync) prevents poisoning the
158	   * PTY PATH with a dir whose binary failed --version.
159	   */
160	  static getManagedBinDirForPath(): string | null {
161	    return RtkService.cachedResolution?.source === 'managed' ? RtkService.getManagedBinDir() : null;
162	  }
163	
164	  private static async resolveBinary(): Promise<{
165	    path: string;
166	    source: RtkSource;
167	    version: string;
168	  } | null> {
169	    const managed = RtkService.getManagedBinPath();
170	    if (existsSync(managed)) {
171	      const version = await RtkService.probeVersion(managed);
172	      if (version === null) {
173	        console.warn('[RtkService] managed binary exists but --version failed:', managed);
174	        return null;
175	      }
176	      return { path: managed, source: 'managed', version };
177	    }
178	
179	    try {
180	      const findCmd = process.platform === 'win32' ? 'where.exe' : 'which';
181	      const { stdout } = await execFileAsync(findCmd, ['rtk']);
182	      const resolved = stdout.trim().split(/\r?\n/)[0]?.trim();
183	      if (resolved) {
184	        const version = await RtkService.probeVersion(resolved);
185	        if (version === null) {
186	          console.warn('[RtkService] PATH binary found but --version failed:', resolved);
187	          return null;
188	        }
189	        return { path: resolved, source: 'path', version };
190	      }
191	    } catch (err) {
192	      // Node's execFile rejects with an Error decorated with `code`: the
193	      // string 'ENOENT' for a missing `which` binary, or the numeric exit
194	      // code for a non-zero exit. Exit 1 from `which`/`where.exe` is the
195	      // "not found" signal — not noise.
196	      const code = (err as { code?: unknown }).code;
197	      if (code !== 'ENOENT' && code !== 1) {
198	        console.warn('[RtkService] which/where.exe lookup failed unexpectedly:', err);
199	      }
200	    }
201	
202	    return null;
203	  }
204	
205	  private static async probeVersion(binPath: string): Promise<string | null> {
206	    try {
207	      const { stdout } = await execFileAsync(binPath, ['--version'], { timeout: 3000 });
208	      return stdout.trim();
209	    } catch (err) {
210	      console.warn(`[RtkService] ${binPath} --version failed:`, err);
211	      return null;
212	    }
213	  }
214	
215	  static getHookCommand(): string | null {
216	    const resolved = RtkService.cachedResolution;
217	    if (!resolved) return null;
218	    // Claude Code runs the hook via sh -c on Unix. Single-quote-escape the
219	    // path so spaces and any shell metachars ($, `, ", \) in the userData
220	    // directory never break or inject into the command.
221	    return `${shellQuoteUnix(resolved.path)} hook claude`;
222	  }
223	
224	  static async getStatus(): Promise<RtkStatus> {
225	    const resolved = await RtkService.resolveBinary();
226	    // Only update the cache on a positive resolution. A transient failure
227	    // (probe timeout, `which` flake) used to clobber a previously-good entry,
228	    // which made getHookCommand() silently return null while isEnabled() on
229	    // disk still said the toggle was ON — the UI would lie about RTK firing.
230	    if (resolved) {
231	      RtkService.cachedResolution = resolved;
232	    }
233	
234	    const downloadable = RtkService.isPlatformDownloadable();
235	    const effective = resolved ?? RtkService.cachedResolution;
236	    if (effective) {
237	      return {
238	        installed: true,
239	        version: effective.version,
240	        path: effective.path,
241	        source: effective.source,
242	        enabled: RtkService.isEnabled(),
243	        downloadable,
244	      };
245	    }
246	    // No binary resolved → enabled is omitted by construction; isEnabled()'s
247	    // disk flag stays put so the toggle restores correctly once a binary
248	    // becomes available again.
249	    return { installed: false, downloadable };
250	  }
251	
252	  /** Populates cachedResolution so getHookCommand() is synchronous later. */
253	  static async warmUp(): Promise<void> {
254	    const resolved = await RtkService.resolveBinary();
255	    if (resolved) {
256	      RtkService.cachedResolution = resolved;
257	      // Backfill the symlink for installs that predate this fix.
258	      if (resolved.source === 'managed') RtkService.ensureUserBinSymlink(resolved.path);
259	    }
260	  }
261	
262	  /**
263	   * Force-clear the cached resolution. Call when the binary has been removed
264	   * from disk (uninstall flow) — there is no read-only path to "the binary is
265	   * gone" elsewhere, so without this, stale cache could keep getHookCommand()
266	   * returning a path that no longer exists.
267	   */
268	  static invalidateCache(): void {
269	    RtkService.cachedResolution = null;
270	  }
271	
272	  // No Windows native release exists upstream — manual-install guidance only there.
273	  private static isPlatformDownloadable(): boolean {
274	    if (process.platform === 'darwin') return true;
275	    if (process.platform === 'linux') return process.arch === 'x64' || process.arch === 'arm64';
276	    return false;
277	  }
278	
279	  private static getReleaseAssetName(): string | null {
280	    if (process.platform === 'darwin') {
281	      return process.arch === 'arm64'
282	        ? 'rtk-aarch64-apple-darwin.tar.gz'
283	        : 'rtk-x86_64-apple-darwin.tar.gz';
284	    }
285	    if (process.platform === 'linux') {
286	      if (process.arch === 'x64') return 'rtk-x86_64-unknown-linux-musl.tar.gz';
287	      if (process.arch === 'arm64') return 'rtk-aarch64-unknown-linux-gnu.tar.gz';
288	    }
289	    return null;
290	  }
291	
292	  /** Single-flight wrapper so double-clicks don't race on the tmp archive. */
293	  static download(): Promise<void> {
294	    if (RtkService.downloadInFlight) return RtkService.downloadInFlight;
295	    RtkService.downloadInFlight = RtkService.doDownload().finally(() => {
296	      RtkService.downloadInFlight = null;
297	    });
298	    return RtkService.downloadInFlight;
299	  }
300	
301	  /**
302	   * Streams RtkDownloadProgress via rtk:downloadProgress AND rejects on failure
303	   * so the IPC caller sees the same error. Progress events are for UI; the
304	   * promise is authoritative.
305	   */
306	  private static async doDownload(): Promise<void> {
307	    const assetName = RtkService.getReleaseAssetName();
308	    if (!assetName) {
309	      const msg = `No rtk release for ${process.platform}/${process.arch}. Install manually from rtk-ai.app.`;
310	      RtkService.emitProgress({ phase: 'error', error: msg });
311	      throw new Error(msg);
312	    }
313	
314	    const binDir = RtkService.getManagedBinDir();
315	    const tmpArchive = join(binDir, `${assetName}.tmp`);
316	    const binPath = RtkService.getManagedBinPath();
317	
318	    try {
319	      RtkService.emitProgress({ phase: 'downloading', percent: 0 });
320	
321	      const apiRes = await fetchWithTimeout(
322	        'https://api.github.com/repos/rtk-ai/rtk/releases/latest',
323	        {
324	          headers: { Accept: 'application/vnd.github+json', 'User-Agent': 'dash-rtk-installer' },
325	        },
326	        FETCH_API_TIMEOUT_MS,
327	      );
328	      if (!apiRes.ok) {
329	        throw new Error(`GitHub API ${apiRes.status}: ${apiRes.statusText}`);
330	      }
331	      const release = (await apiRes.json()) as unknown;
332	      if (!isReleasePayload(release)) {
333	        throw new Error(`Unexpected GitHub API response: ${JSON.stringify(release).slice(0, 200)}`);
334	      }
335	
336	      const asset = release.assets.find((a) => a.name === assetName);
337	      if (!asset) {
338	        throw new Error(`Release ${release.tag_name} has no asset "${assetName}"`);
339	      }
340	      assertTrustedDownloadUrl(asset.browser_download_url);
341	
342	      const checksumAsset = release.assets.find((a) => a.name === 'checksums.txt');
343	      if (!checksumAsset) {
344	        throw new Error(`Release ${release.tag_name} has no checksums.txt — refusing to install.`);
345	      }
346	      assertTrustedDownloadUrl(checksumAsset.browser_download_url);
347	
348	      if (!existsSync(binDir)) mkdirSync(binDir, { recursive: true });
349	
350	      const expectedSha = await RtkService.fetchExpectedSha256(
351	        checksumAsset.browser_download_url,
352	        assetName,
353	      );
354	
355	      // GitHub's release CDN occasionally serves truncated/corrupt bytes;
356	      // retry a few times before surfacing an error to the user.
357	      const MAX_ATTEMPTS = 3;
358	      let lastError: Error | null = null;
359	      for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
360	        try {
361	          await RtkService.fetchToFile(asset.browser_download_url, tmpArchive);
362	          RtkService.emitProgress({ phase: 'verifying' });
363	          await RtkService.verifyChecksum(tmpArchive, expectedSha);
364	          await RtkService.verifyArchive(tmpArchive);
365	          lastError = null;
366	          break;
367	        } catch (err) {
368	          lastError = err instanceof Error ? err : new Error(String(err));
369	          console.warn(`[RtkService.download] attempt ${attempt} failed:`, lastError.message);
370	          rmSync(tmpArchive, { force: true });
371	          if (attempt < MAX_ATTEMPTS) {
372	            RtkService.emitProgress({ phase: 'downloading', percent: 0 });
373	          }
374	        }
375	      }
376	      if (lastError) {
377	        throw new Error(
378	          `Download repeatedly failed (${MAX_ATTEMPTS} attempts): ${lastError.message}`,
379	        );
380	      }
381	
382	      RtkService.emitProgress({ phase: 'extracting' });
383	      try {
384	        await RtkService.extractTarball(tmpArchive, binDir);
385	      } catch (err) {
386	        // Partial extraction may have dropped a half-written binary.
387	        rmSync(binPath, { force: true });
388	        throw err;
389	      }
390	
391	      if (!existsSync(binPath)) {
392	        throw new Error(`Archive did not contain expected binary at ${binPath}`);
393	      }
394	      // Defense-in-depth: even though verifyArchive rejected symlinks/hardlinks
395	      // at preflight, lstat the extracted binary before chmod. chmodSync on a
396	      // symlink would follow the link and modify the target instead of binPath.
397	      const stat = lstatSync(binPath);
398	      if (!stat.isFile()) {
399	        rmSync(binPath, { force: true });
400	        throw new Error(`Extracted binary is not a regular file at ${binPath}`);
401	      }
402	      // Must chmod before the probeVersion spawn below; tar on some systems drops +x.
403	      chmodSync(binPath, 0o755);
404	
405	      RtkService.cachedResolution = await RtkService.resolveBinary();
406	      if (!RtkService.cachedResolution) {
407	        rmSync(binPath, { force: true });
408	        throw new Error('Installed binary failed to report --version; removed.');
409	      }
410	      RtkService.ensureUserBinSymlink(RtkService.cachedResolution.path);
411	
412	      RtkService.emitProgress({ phase: 'done', version: release.tag_name });
413	    } catch (err) {
414	      const message = err instanceof Error ? err.message : String(err);
415	      RtkService.emitProgress({ phase: 'error', error: message });
416	      throw err instanceof Error ? err : new Error(message);
417	    } finally {
418	      rmSync(tmpArchive, { force: true });
419	    }
420	  }
421	
422	  private static async fetchExpectedSha256(url: string, assetName: string): Promise<string> {
423	    const res = await fetchWithTimeout(url, {}, FETCH_API_TIMEOUT_MS);
424	    if (!res.ok) throw new Error(`Failed to fetch checksums.txt: ${res.status} ${res.statusText}`);
425	    const body = await res.text();
426	    for (const line of body.split(/\r?\n/)) {
427	      // The `\*?` accepts the BSD "binary mode" marker some sha256sum
428	      // implementations emit; without it those releases would fail to match.
429	      const match = line.match(/^([a-f0-9]{64})\s+\*?(.+?)\s*$/i);
430	      if (match && match[2] === assetName) return match[1]!.toLowerCase();
431	    }
432	    throw new Error(`checksums.txt does not list ${assetName}`);
433	  }
434	
435	  private static verifyChecksum(filePath: string, expectedSha: string): Promise<void> {
436	    return verifyChecksum(filePath, expectedSha);
437	  }
438	
439	  private static async fetchToFile(url: string, dest: string): Promise<void> {
440	    const controller = new AbortController();
441	    const wallTimer = setTimeout(() => controller.abort(), FETCH_BODY_TIMEOUT_MS);
442	    try {
443	      const dlRes = await fetch(url, { signal: controller.signal });
444	      if (!dlRes.ok || !dlRes.body) {
445	        throw new Error(`Download failed: ${dlRes.status} ${dlRes.statusText}`);
446	      }
447	      const total = Number(dlRes.headers.get('content-length') || '0');
448	      let transferred = 0;
449	
450	      const source = Readable.fromWeb(dlRes.body as unknown as WebReadableStream<Uint8Array>);
451	      source.on('data', (chunk: Buffer) => {
452	        transferred += chunk.length;
453	        if (total > 0) {
454	          RtkService.emitProgress({
455	            phase: 'downloading',
456	            percent: Math.min(99, Math.round((transferred / total) * 100)),
457	          });
458	        }
459	      });
460	      await pipeline(source, createWriteStream(dest));
461	      if (total > 0 && transferred !== total) {
462	        throw new Error(`Truncated download: expected ${total} bytes, got ${transferred}.`);
463	      }
464	      RtkService.emitProgress({ phase: 'downloading', percent: 100 });
465	    } finally {
466	      clearTimeout(wallTimer);
467	    }
468	  }
469	
470	  private static async verifyArchive(archivePath: string): Promise<void> {
471	    try {
472	      // Validates every member is relative, stays inside dest, AND is a
473	      // regular file or directory — symlinks/hardlinks are refused outright
474	      // because tar honors their targets at extract time, which would let a
475	      // crafted archive write outside dest even though the entry name is safe.
476	      const entries = await RtkService.listTarball(archivePath);
477	      const dest = RtkService.getManagedBinDir();
478	      for (const entry of entries) {
479	        assertSafeArchiveMember(entry, dest);
480	      }
481	    } catch (err) {
482	      const detail = err instanceof Error ? err.message : String(err);
483	      throw new Error(`Archive integrity check failed: ${detail}`);
484	    }
485	  }
486	
487	  private static async extractTarball(archivePath: string, destDir: string): Promise<void> {
488	    // Plain extract first (rtk's releases put the binary at the archive root).
489	    // If the binary still isn't where we expect, retry with --strip-components=1
490	    // for archives that nest the binary under a top-level directory.
491	    await RtkService.runTar(['-xzf', archivePath, '-C', destDir, '--no-same-owner']);
492	    if (existsSync(RtkService.getManagedBinPath())) return;
493	    console.warn('[RtkService] binary not at archive root, retrying with --strip-components=1');
494	    await RtkService.runTar([
495	      '-xzf',
496	      archivePath,
497	      '-C',
498	      destDir,
499	      '--strip-components=1',
500	      '--no-same-owner',
501	    ]);
502	  }
503	
504	  private static listTarball(archivePath: string): Promise<TarEntry[]> {
505	    return new Promise((resolveP, rejectP) => {
506	      // -tvf prints "<mode> <owner> <size> <mtime> <name>[ -> target]" per entry.
507	      // The first char of the mode column is the file type ('-' regular, 'd'
508	      // directory, 'l' symlink, 'h' hardlink); we use it to reject link types
509	      // before extraction. Both BSD (macOS) and GNU tar use this format.
510	      const proc = spawn('tar', ['-tvzf', archivePath], {
511	        stdio: ['ignore', 'pipe', 'pipe'],
512	        timeout: TAR_TIMEOUT_MS,
513	      });
514	      let stdout = '';
515	      let stderr = '';
516	      proc.stdout.on('data', (d: Buffer) => {
517	        stdout += d.toString();
518	      });
519	      proc.stderr.on('data', (d: Buffer) => {
520	        stderr += d.toString();
521	      });
522	      proc.on('error', (err: NodeJS.ErrnoException) => {
523	        if (err.code === 'ENOENT') {
524	          rejectP(new Error('`tar` is not available on PATH. Install it and retry.'));
525	        } else {
526	          rejectP(err);
527	        }
528	      });
529	      proc.on('exit', (code, signal) => {
530	        if (signal) rejectP(new Error(`tar -tvzf killed by signal ${signal} (timed out?)`));
531	        else if (code === 0) resolveP(parseTarVerbose(stdout));
532	        else rejectP(new Error(`tar -tvzf exited ${code}: ${stderr.trim()}`));
533	      });
534	    });
535	  }
536	
537	  private static runTar(args: string[]): Promise<void> {
538	    return new Promise((resolveP, rejectP) => {
539	      const proc = spawn('tar', args, {
540	        stdio: ['ignore', 'ignore', 'pipe'],
541	        timeout: TAR_TIMEOUT_MS,
542	      });
543	      let stderr = '';
544	      proc.stderr?.on('data', (d: Buffer) => {
545	        stderr += d.toString();
546	      });
547	      proc.on('error', (err: NodeJS.ErrnoException) => {
548	        if (err.code === 'ENOENT') {
549	          rejectP(new Error('`tar` is not available on PATH. Install it and retry.'));
550	        } else {
551	          rejectP(err);
552	        }
553	      });
554	      proc.on('exit', (code, signal) => {
555	        if (signal) rejectP(new Error(`tar killed by signal ${signal} (timed out?)`));
556	        else if (code === 0) resolveP();
557	        else rejectP(new Error(`tar exited ${code}: ${stderr.trim()}`));
558	      });
559	    });
560	  }
561	
562	  private static emitProgress(progress: RtkDownloadProgress): void {
563	    const sender = RtkService.sender;
564	    if (sender && !sender.isDestroyed()) {
565	      sender.send('rtk:downloadProgress', progress);
566	    }
567	  }
568	
569	  /** Exercises `rtk hook claude` end-to-end so Settings can prove the binary rewrites. */
570	  static async runHookTest(): Promise<RtkTestResult> {
571	    const resolved = RtkService.cachedResolution ?? (await RtkService.resolveBinary());
572	    if (!resolved) {
573	      return { ok: false, error: 'rtk is not installed' };
574	    }
575	
576	    const testedCommand = 'git status';
577	    const input = JSON.stringify({
578	      hook_event_name: 'PreToolUse',
579	      tool_name: 'Bash',
580	      tool_input: { command: testedCommand, description: 'RTK self-test' },
581	    });
582	
583	    try {
584	      const { stdout, stderr, code, signal } = await pipeStdin(
585	        resolved.path,
586	        ['hook', 'claude'],
587	        input,
588	        10_000,
589	      );
590	
591	      if (/panic|unwrap|segfault/i.test(stderr)) {
592	        return { ok: false, testedCommand, error: `rtk crashed: ${stderr.trim().slice(0, 400)}` };
593	      }
594	      if (code === null) {
595	        return {
596	          ok: false,
597	          testedCommand,
598	          error: `rtk killed by signal ${signal ?? 'unknown'} (likely timeout)`,
599	        };
600	      }
601	      // rtk exits 2 to signal "block this tool call" — a valid hook result, not an error.
602	      if (code !== 0 && code !== 2) {
603	        return {
604	          ok: false,
605	          testedCommand,
606	          error: `rtk exited ${code}${stderr ? ': ' + stderr.trim().slice(0, 400) : ''}`,
607	        };
608	      }
609	
610	      const extracted = extractRewrittenCommand(stdout);
611	      if (!extracted.ok) {
612	        return {
613	          ok: false,
614	          testedCommand,
615	          error: `rtk produced unparsable output: ${extracted.reason}`,
616	        };
617	      }
618	
619	      const rawOutput = stdout.slice(0, 2000);
620	
621	      // exit 2 → blocked, regardless of any rewrite payload.
622	      if (code === 2) {
623	        return {
624	          ok: true,
625	          testedCommand,
626	          rawOutput,
627	          outcome: { kind: 'blocked', stderr: stderr.trim().slice(0, 400) },
628	        };
629	      }
630	
631	      const rewriteCmd = extracted.command;
632	      const isRewrite = rewriteCmd !== null && rewriteCmd !== testedCommand;
633	      if (isRewrite) {
634	        // execDiff is best-effort visualization; capture failures are
635	        // forwarded as `kind: 'failed'` so the UI can warn instead of
636	        // collapsing to "rtk chose pass-through".
637	        const execDiff = await RtkService.captureExecDiff(testedCommand, rewriteCmd);
638	        return {
639	          ok: true,
640	          testedCommand,
641	          rawOutput,
642	          outcome: { kind: 'rewritten', rewrittenCommand: rewriteCmd, execDiff },
643	        };
644	      }
645	
646	      return { ok: true, testedCommand, rawOutput, outcome: { kind: 'pass-through' } };
647	    } catch (err) {
648	      return { ok: false, testedCommand, error: err instanceof Error ? err.message : String(err) };
649	    }
650	  }
651	
652	  /**
653	   * Execute both the raw and rtk-rewritten commands inside a throwaway git
654	   * repo populated with enough untracked files to make `git status` verbose.
655	   * Returns a `failed` variant on any error rather than null — the previous
656	   * null-on-error meant the UI rendered the green "rtk chose pass-through"
657	   * card for genuine failures (missing git, EACCES on tmpdir, rtk panic).
658	   */
659	  private static async captureExecDiff(
660	    rawCommand: string,
661	    rewrittenCommand: string,
662	  ): Promise<import('@shared/types').RtkExecDiff> {
663	    let dir: string;
664	    try {
665	      dir = await mkdtemp(join(tmpdir(), 'dash-rtk-verify-'));
666	    } catch (err) {
667	      return {
668	        kind: 'failed',
669	        stage: 'setup',
670	        reason: `Couldn't create temp dir: ${err instanceof Error ? err.message : String(err)}`,
671	      };
672	    }
673	
674	    try {
675	      // Give `git status` something non-trivial to emit — multiple files
676	      // across a few directories so rtk's grouping/dedup filters have work.
677	      await Promise.all([
678	        writeFile(join(dir, 'package.json'), '{}\n'),
679	        writeFile(join(dir, 'README.md'), '# test\n'),
680	        writeFile(join(dir, 'config.toml'), '[section]\nvalue = 1\n'),
681	        mkdir(join(dir, 'src')).then(() =>
682	          Promise.all([
683	            writeFile(join(dir, 'src', 'index.ts'), 'export {};\n'),
684	            writeFile(join(dir, 'src', 'lib.ts'), 'export {};\n'),
685	            writeFile(join(dir, 'src', 'types.ts'), 'export {};\n'),
686	          ]),
687	        ),
688	        mkdir(join(dir, 'tests')).then(() =>
689	          Promise.all([
690	            writeFile(join(dir, 'tests', 'a.test.ts'), 'test\n'),
691	            writeFile(join(dir, 'tests', 'b.test.ts'), 'test\n'),
692	          ]),
693	        ),
694	      ]);
695	
696	      const initRes = await runShell('git init -q', dir);
697	      if (initRes.code !== 0) {
698	        return {
699	          kind: 'failed',
700	          stage: 'setup',
701	          exitCode: initRes.code ?? undefined,
702	          stderr: initRes.stderr.slice(0, 400),
703	          reason: `git init failed (exit ${initRes.code ?? 'null'}). Is git installed?`,
704	        };
705	      }
706	
707	      // Make sure rtk resolves from the rewritten command even when the user
708	      // never installed it on the system PATH — prepend our managed bin dir.
709	      const managedDir = RtkService.getManagedBinDirForPath();
710	      const pathWithRtk = [managedDir, process.env.PATH].filter(Boolean).join(delimiter);
711	      const env = { ...process.env, PATH: pathWithRtk };
712	
713	      const [rawRes, rewrittenRes] = await Promise.all([
714	        runShell(rawCommand, dir, env),
715	        runShell(rewrittenCommand, dir, env),
716	      ]);
717	
718	      if (rawRes.code !== 0) {
719	        return {
720	          kind: 'failed',
721	          stage: 'raw',
722	          exitCode: rawRes.code ?? undefined,
723	          stderr: rawRes.stderr.slice(0, 400),
724	          reason: `Raw command exited ${rawRes.code ?? 'null'}: ${rawCommand}`,
725	        };
726	      }
727	      if (rewrittenRes.code !== 0) {
728	        return {
729	          kind: 'failed',
730	          stage: 'rewritten',
731	          exitCode: rewrittenRes.code ?? undefined,
732	          stderr: rewrittenRes.stderr.slice(0, 400),
733	          reason: `Rewritten command exited ${rewrittenRes.code ?? 'null'}: ${rewrittenCommand}`,
734	        };
735	      }
736	
737	      // Trim IPC payload. When stdout hit the cap, byte counts reflect the
738	      // truncated buffer (we stopped reading) — surface that via `truncated`
739	      // so the UI can warn instead of advertising a misleading savings %.
740	      const DISPLAY_CAP = 8 * 1024;
741	      return {
742	        kind: 'ok',
743	        rawStdout: rawRes.stdout.slice(0, DISPLAY_CAP),
744	        compressedStdout: rewrittenRes.stdout.slice(0, DISPLAY_CAP),
745	        rawBytes: Buffer.byteLength(rawRes.stdout),
746	        compressedBytes: Buffer.byteLength(rewrittenRes.stdout),
747	        truncated: rawRes.truncated || rewrittenRes.truncated,
748	      };
749	    } catch (err) {
750	      console.warn('[RtkService.captureExecDiff] unexpected:', err);
751	      return {
752	        kind: 'failed',
753	        stage: 'unknown',
754	        reason: err instanceof Error ? err.message : String(err),
755	      };
756	    } finally {
757	      await rm(dir, { recursive: true, force: true }).catch((err) => {
758	        console.warn('[RtkService.captureExecDiff] tmpdir cleanup failed:', err);
759	      });
760	    }
761	  }
762	}
763	
764	// ── Helpers (module-private) ───────────────────────────────────────────────
765	
766	/**
767	 * Run a shell string and capture its stdout/stderr up to a hard cap. Used by
768	 * the Test RTK flow to exec both the raw command (e.g. `git status`) and the
769	 * rtk-rewritten version (e.g. `rtk git status`) in a controlled environment.
770	 */
771	const RUN_SHELL_OUTPUT_CAP = 64 * 1024;
772	
773	function runShell(
774	  cmd: string,
775	  cwd: string,
776	  env: NodeJS.ProcessEnv = process.env,
777	  timeoutMs = 15_000,
778	): Promise<{ stdout: string; stderr: string; code: number | null; truncated: boolean }> {
779	  return new Promise((resolveP, rejectP) => {
780	    const shell = process.platform === 'win32' ? 'cmd.exe' : 'sh';
781	    const args = process.platform === 'win32' ? ['/c', cmd] : ['-c', cmd];
782	    const proc = spawn(shell, args, { cwd, env, timeout: timeoutMs });
783	    let stdout = '';
784	    let stderr = '';
785	    let truncated = false;
786	    proc.stdout.on('data', (c: Buffer) => {
787	      if (stdout.length < RUN_SHELL_OUTPUT_CAP) stdout += c.toString();
788	      else truncated = true;
789	    });
790	    proc.stderr.on('data', (c: Buffer) => {
791	      if (stderr.length < RUN_SHELL_OUTPUT_CAP) stderr += c.toString();
792	      else truncated = true;
793	    });
794	    proc.on('error', rejectP);
795	    proc.on('close', (code) => resolveP({ stdout, stderr, code, truncated }));
796	  });
797	}
798	
799	function pipeStdin(
800	  cmd: string,
801	  args: string[],
802	  stdin: string,
803	  timeoutMs: number,
804	): Promise<{ code: number | null; signal: NodeJS.Signals | null; stdout: string; stderr: string }> {
805	  return new Promise((resolveP, rejectP) => {
806	    const proc = spawn(cmd, args, { timeout: timeoutMs });
807	    let stdout = '';
808	    let stderr = '';
809	    proc.stdout.on('data', (c: Buffer) => {
810	      stdout += c.toString();
811	    });
812	    proc.stderr.on('data', (c: Buffer) => {
813	      stderr += c.toString();
814	    });
815	    // rtk may exit before reading stdin; EPIPE must not become unhandled.
816	    proc.stdin.on('error', (err: NodeJS.ErrnoException) => {
817	      if (err.code !== 'EPIPE') {
818	        console.warn('[RtkService.pipeStdin] unexpected stdin error:', err);
819	      }
820	    });
821	    proc.on('error', rejectP);
822	    proc.on('close', (code, signal) => resolveP({ code, signal, stdout, stderr }));
823	    proc.stdin.write(stdin);
824	    proc.stdin.end();
825	  });
826	}
827	
828	type ExtractResult = { ok: true; command: string | null } | { ok: false; reason: string };
829	
830	function extractRewrittenCommand(stdout: string): ExtractResult {
831	  const trimmed = stdout.trim();
832	  if (!trimmed) return { ok: true, command: null };
833	  let parsed: Record<string, unknown>;
834	  try {
835	    parsed = JSON.parse(trimmed) as Record<string, unknown>;
836	  } catch (err) {
837	    return { ok: false, reason: err instanceof Error ? err.message : String(err) };
838	  }
839	  // Claude Code's hook JSON schema has evolved; accept both historical and
840	  // current field names so version skew between rtk releases and Dash's
841	  // expectations doesn't silently render as "pass-through".
842	  const hso = isObject(parsed.hookSpecificOutput) ? parsed.hookSpecificOutput : null;
843	  const candidates: unknown[] = [
844	    hso?.updatedInput,
845	    hso?.modifiedToolInput,
846	    hso?.updatedToolInput,
847	    parsed.updatedInput,
848	    parsed.modifiedToolInput,
849	    parsed.updatedToolInput,
850	    parsed.tool_input,
851	  ];
852	  for (const node of candidates) {
853	    if (isObject(node) && typeof node.command === 'string') {
854	      return { ok: true, command: node.command };
855	    }
856	  }
857	  return { ok: true, command: null };
858	}
859	
860	function isObject(v: unknown): v is Record<string, unknown> {
861	  return !!v && typeof v === 'object';
862	}
863	
864	function shellQuoteUnix(s: string): string {
865	  return `'${s.replace(/'/g, "'\\''")}'`;
866	}
867	
868	interface ReleasePayload {
869	  tag_name: string;
870	  assets: Array<{ name: string; browser_download_url: string }>;
871	}
872	
873	function isReleasePayload(v: unknown): v is ReleasePayload {
874	  if (!isObject(v)) return false;
875	  if (typeof v.tag_name !== 'string') return false;
876	  if (!Array.isArray(v.assets)) return false;
877	  return v.assets.every(
878	    (a) => isObject(a) && typeof a.name === 'string' && typeof a.browser_download_url === 'string',
879	  );
880	}
881	
882	function assertTrustedDownloadUrl(raw: string): void {
883	  let url: URL;
884	  try {
885	    url = new URL(raw);
886	  } catch {
887	    throw new Error(`Refusing malformed asset URL: ${raw}`);
888	  }
889	  if (url.protocol !== 'https:') {
890	    throw new Error(`Refusing non-HTTPS asset URL: ${raw}`);
891	  }
892	  const host = url.hostname.toLowerCase();
893	  const allowed =
894	    host === 'github.com' ||
895	    host === 'api.github.com' ||
896	    host === 'objects.githubusercontent.com' ||
897	    host.endsWith('.githubusercontent.com');
898	  if (!allowed) {
899	    throw new Error(`Refusing asset URL outside GitHub: ${raw}`);
900	  }
901	}
