903	type TarMemberType = 'file' | 'dir' | 'symlink' | 'hardlink' | 'other';
904	
905	interface TarEntry {
906	  /** First char of the mode column from `tar -tvf` (`-`, `d`, `l`, `h`, ...). */
907	  type: TarMemberType;
908	  name: string;
909	}
910	
911	function parseTarVerbose(stdout: string): TarEntry[] {
912	  const out: TarEntry[] = [];
913	  for (const line of stdout.split(/\r?\n/)) {
914	    if (!line) continue;
915	    // Lines start with the mode string; first char encodes the file type.
916	    const typeChar = line[0];
917	    let type: TarMemberType;
918	    switch (typeChar) {
919	      case '-':
920	        type = 'file';
921	        break;
922	      case 'd':
923	        type = 'dir';
924	        break;
925	      case 'l':
926	        type = 'symlink';
927	        break;
928	      case 'h':
929	        type = 'hardlink';
930	        break;
931	      default:
932	        type = 'other';
933	    }
934	    // Strip "<name> -> <target>" tail so name validation only sees the entry path.
935	    // The target itself doesn't need validation: we reject symlinks/hardlinks outright.
936	    const arrow = line.indexOf(' -> ');
937	    const trail = arrow >= 0 ? line.slice(0, arrow) : line;
938	    // Name is the last whitespace-delimited token (mode/owner/size/date have
939	    // varying field counts between BSD and GNU tar; the name is always last).
940	    const tokens = trail.split(/\s+/);
941	    const name = tokens[tokens.length - 1];
942	    if (name) out.push({ type, name });
943	  }
944	  return out;
945	}
946	
947	function assertSafeArchiveMember(entry: TarEntry, destDir: string): void {
948	  // Refuse symlinks/hardlinks outright. `tar -xzf` honors their targets at
949	  // extract time, so a crafted archive with `rtk -> /etc/passwd` would let
950	  // chmod/exec follow the link out of dest even though the entry name is
951	  // benign. Defense-in-depth: SHA-256 + URL allowlist already make this hard
952	  // to reach, but the link types themselves are never legitimate in an rtk
953	  // release tarball.
954	  if (entry.type === 'symlink' || entry.type === 'hardlink') {
955	    throw new Error(`Archive contains ${entry.type}, which is not allowed: ${entry.name}`);
956	  }
957	  if (entry.type === 'other') {
958	    throw new Error(`Archive contains unsupported member type: ${entry.name}`);
959	  }
960	  // Reject embedded null bytes — tar entries should never contain them, and
961	  // some libcs truncate at \0 which could let a malicious entry name slip
962	  // past a downstream check.
963	  if (entry.name.includes('\0')) {
964	    throw new Error(`Archive member contains null byte: ${JSON.stringify(entry.name)}`);
965	  }
966	  // Reject absolute paths. The Windows-drive regex runs on every platform by
967	  // design: a tarball authored on Windows can reach any OS, so we refuse
968	  // `C:\...` entries regardless of where extraction happens.
969	  if (entry.name.startsWith('/') || /^[a-zA-Z]:[\\/]/.test(entry.name)) {
970	    throw new Error(`Archive contains absolute path: ${entry.name}`);
971	  }
972	  // Normalize backslashes to forward slashes before resolve(). On POSIX,
973	  // path.resolve treats `\` as a literal filename character, so `..\\evil`
974	  // would not be recognised as a parent-traversal attempt without this step.
975	  const normalized = normalize(entry.name.replace(/\\/g, '/'));
976	  const resolved = resolve(destDir, normalized);
977	  const base = resolve(destDir) + sep;
978	  if (resolved !== resolve(destDir) && !resolved.startsWith(base)) {
979	    throw new Error(`Archive member escapes destDir: ${entry.name}`);
980	  }
981	}
982	
983	async function verifyChecksum(filePath: string, expectedSha: string): Promise<void> {
984	  const hash = createHash('sha256');
985	  await pipeline(createReadStream(filePath), hash);
986	  const actual = hash.digest('hex');
987	  if (actual !== expectedSha) {
988	    throw new Error(
989	      `Checksum mismatch: expected ${expectedSha}, got ${actual}. Refusing to install.`,
990	    );
991	  }
992	}
993	
994	async function fetchWithTimeout(
995	  url: string,
996	  init: RequestInit,
997	  timeoutMs: number,
998	): Promise<Response> {
999	  const controller = new AbortController();
1000	  const timer = setTimeout(() => controller.abort(), timeoutMs);
1001	  try {
1002	    return await fetch(url, { ...init, signal: controller.signal });
1003	  } finally {
1004	    clearTimeout(timer);
1005	  }
1006	}
1007	
1008	/**
1009	 * Best-effort: create or refresh a symlink at `linkPath` pointing at `target`.
1010	 * Never throws; install must not fail because the symlink could not be made.
1011	 * Refuses to overwrite a non-symlink at the destination so a user-installed
1012	 * `rtk` (e.g. via cargo) is not clobbered.
1013	 */
1014	function ensureUserBinSymlink(target: string, linkPath: string): void {
1015	  try {
1016	    mkdirSync(dirname(linkPath), { recursive: true });
1017	    if (existsSync(linkPath)) {
1018	      const stat = lstatSync(linkPath);
1019	      if (!stat.isSymbolicLink()) return;
1020	      if (readlinkSync(linkPath) === target) return;
1021	      rmSync(linkPath);
1022	    }
1023	    symlinkSync(target, linkPath);
1024	  } catch (err) {
1025	    console.warn('[RtkService] could not create user-bin symlink:', err);
1026	  }
1027	}
1028	
1029	/**
1030	 * Test-only exports of module-private helpers. Importing from here keeps the
1031	 * unit tests exercising the real code instead of a drifting re-implementation.
1032	 */
1033	export const __test__ = {
1034	  assertTrustedDownloadUrl,
1035	  assertSafeArchiveMember,
1036	  parseTarVerbose,
1037	  shellQuoteUnix,
1038	  extractRewrittenCommand,
1039	  verifyChecksum,
1040	  ensureUserBinSymlink,
1041	};
